script:
frappe.ui.form.on("Quotation", {
    after_save: function(frm) {
        if (frm.doc.custom_quotation_status === "Approved") {
            frappe.db.get_list("Asset Maintenance Log", {
                filters: { custom_quotation: frm.doc.name },
                fields: ["name"]
            }).then((logs) => {
                logs.forEach((log) => {
                    frappe.db.set_value(
                        "Asset Maintenance Log",
                        log.name,
                        "custom_quotation_status",
                        "Quotation approved"
                    );
                });
            });
        }
    }
});
